# Hearthside's manual infrastructure (#217, spec #69): what the deploy
# workflows can't do. Run it once per environment, dev first:
#
#   scripts/hearthside-wizard.sh dev     after the spec merges into dev and
#                                        dev's deploy has finished
#   scripts/hearthside-wizard.sh prod    after the promotion to main has
#                                        deployed, and dev works end to end
#
# Until this has run, Hearthside's container runs in the ECS task but no ALB
# rule or DNS record leads to it, and HEARTHSIDE_LIVE is off, so the backend
# and the portfolio behave exactly as before.
#
# Stages, each checked before and after, and skipped when already done
# (the issue's steps in brackets):
#    1  Tools and accounts
#    2  Hearthside's image repository and container
#    3  Security group: the ALB may reach port 3002
#    4  Target group                                         [step 1]
#    5  ALB listener rule for the Hearthside host           [step 2]
#    6  Register the target group with the ECS service      [step 1]
#    7  Certificate: a second ACM certificate on dev;       [step 3]
#       prod is covered by the main one
#    8  Route 53 record for the Hearthside host             [step 4]
#    9  Google Cloud Console: origins and redirect URI      [step 5]
#   10  Dev and prod sign with different JWT secrets        [step 7]
#   11  Turn the switch on: HEARTHSIDE_URL and the          [step 6]
#       portfolio's redirects, then redeploy
#
# The target group can only join the ECS service once a listener rule ties it
# to the ALB, so the rule (5) comes before the registration (6).
#
# Needs: aws (CLI v2, signed in to account 913447902637 with rights to ECS,
# ELBv2, EC2 security groups, ACM, Route 53, Secrets Manager and ECR), gh
# (signed in), node, curl and openssl. Git Bash is fine. Every change shows
# its command and asks first; checks run without asking. The ARNs it creates
# are noted in ~/.pwa-hearthside-wizard.env (HEARTHSIDE_WIZARD_STATE to move it).

usage() {
  printf 'Usage: %s dev|prod\n' "$0"
  printf '  Walks through Hearthside'"'"'s ALB, ACM, Route 53, Google and switch steps for one environment.\n'
  printf '  Run dev first; prod after the promotion to main has deployed.\n'
}

case "${1:-}" in
