# Git Bash rewrites arguments that start with "/" into Windows paths (so
# "--health-check-path /health" would arrive as C:/Program Files/Git/health).
export MSYS_NO_PATHCONV=1 MSYS2_ARG_CONV_EXCL='*'
export AWS_REGION=us-east-2 AWS_DEFAULT_REGION=us-east-2 AWS_PAGER=""

# The AWS CLI on Windows ends its lines with CRLF; strip the CRs so values
# compare and interpolate cleanly. pipefail keeps aws's exit status.
aws() { command aws "$@" | tr -d '\r'; }
# js 'code' args... : run a small node program; stdin is available as IN.
js() {
  local code="$1"; shift
  node -e "const IN=(()=>{try{return require('fs').readFileSync(0,'utf8')}catch{return ''}})(); $code" "$@" | tr -d '\r'
}

pass() { printf '  %s✓ %s%s\n' "$GREEN" "$1" "$RESET"; }
bad()  { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET"; }
stop() {
  bad "$1"
  note "Fix that, then re-run: $0 $ENV_NAME (finished stages are checked and skipped)."
  exit 1
}
# show_cmd cmd args... : print a command, quoted, as it will run.
show_cmd() {
  local out="" a
  for a in "$@"; do out+="$(printf '%q' "$a") "; done
  printf '    %s$ %s%s\n' "$DIM" "$out" "$RESET"
}
# change "what" cmd args... : show a change, ask, then make it. Its output is
# left in CHANGE_OUT. Returns 1 when declined.
CHANGE_OUT=""
change() {
  local what="$1"; shift
  say "$what"
  show_cmd "$@"
  if confirm "Make this change?"; then
    if CHANGE_OUT=$("$@"); then
      pass "done"
    else
      bad "that command failed (its error is above)"
      return 1
    fi
  else
    warn "not changed"
    return 1
  fi
}
none() { [[ -z "$1" || "$1" == "None" || "$1" == "null" ]]; }
# health_via HOSTHEADER CONNECT_TO_HOST [-k] : headers of GET /health on the
# Hearthside host, sent to CONNECT_TO_HOST (the ALB, or the host itself).
health_headers() {
  local target="$1"; shift
  curl -sS -m 15 -D - -o /dev/null --connect-to "$HOST:443:$target:443" "$@" "https://$HOST/health" 2>&1 | tr -d '\r' || true
}
served_by_hearthside() { grep -qi '^x-served-by: *hearthside' <<<"$1"; }
# some_healthy "states" : at least one target is healthy (others may be draining).
some_healthy() { tr '\t' '\n' <<<"$1" | grep -qx healthy; }

# Looked up once, in stage 2/3, and used after.
TASK_DEF_ARN="" FRONTEND_TG_ARN="" FRONTEND_PORT="" ALB_ARN="" ALB_DNS="" ALB_ZONE="" ALB_IP_TYPE="" LISTENER_ARN="" TG_ARN="" ZONE_ID=""

# discover_layout : the service, its portfolio target group, the ALB and its
# HTTPS listener. Read-only.
discover_layout() {
  [[ -n "$LISTENER_ARN" ]] && return 0
  local svc
  svc=$(aws ecs describe-services --cluster "$CLUSTER" --services "$SERVICE" --output json)
  TASK_DEF_ARN=$(js 'const s=JSON.parse(IN).services[0]; console.log(s?s.taskDefinition:"")' <<<"$svc")
  none "$TASK_DEF_ARN" && stop "No ECS service $SERVICE in cluster $CLUSTER."
  read -r FRONTEND_TG_ARN FRONTEND_PORT < <(js 'const lb=(JSON.parse(IN).services[0].loadBalancers||[]).find(l=>l.containerName==="frontend"); console.log(lb?lb.targetGroupArn+" "+lb.containerPort:"")' <<<"$svc") || true
  none "$FRONTEND_TG_ARN" && stop "The service has no load balancer entry for the frontend container; this wizard expects the portfolio behind the ALB."
  ALB_ARN=$(aws elbv2 describe-target-groups --target-group-arns "$FRONTEND_TG_ARN" --query 'TargetGroups[0].LoadBalancerArns[0]' --output text)
  read -r ALB_DNS ALB_ZONE ALB_IP_TYPE < <(aws elbv2 describe-load-balancers --load-balancer-arns "$ALB_ARN" --query 'LoadBalancers[0].[DNSName,CanonicalHostedZoneId,IpAddressType]' --output text) || true
  none "$ALB_DNS" && stop "Couldn't read the ALB behind the portfolio's target group."
  LISTENER_ARN=$(aws elbv2 describe-listeners --load-balancer-arn "$ALB_ARN" --query 'Listeners[?Port==`443`].ListenerArn | [0]' --output text)
  none "$LISTENER_ARN" && stop "The ALB has no listener on 443."
  return 0
}

find_tg() {
  TG_ARN=$(aws elbv2 describe-target-groups --names "$TG_NAME" --query 'TargetGroups[0].TargetGroupArn' --output text 2>/dev/null || true)
  none "$TG_ARN" && TG_ARN=""
  return 0
}

find_zone() {
  [[ -n "$ZONE_ID" ]] && return 0
  local zone
  zone=$(aws route53 list-hosted-zones-by-name --dns-name "$ZONE_NAME" --max-items 1 --query 'HostedZones[0].[Name,Id]' --output text)
  [[ "${zone%%$'\t'*}" == "$ZONE_NAME." ]] || stop "No Route 53 hosted zone for $ZONE_NAME."
  ZONE_ID="${zone##*/}"
}

# validation_record CERT_ARN : "name value" of each DNS validation CNAME.
validation_records() {
  aws acm describe-certificate --certificate-arn "$1" --query 'Certificate.DomainValidationOptions[].ResourceRecord.[Name,Value]' --output text | sort -u
}
# check_validation_records CERT_ARN : each validation CNAME is in Route 53.
# ACM renews only while they are there (the 2026-10-02 outage).
check_validation_records() {
  local cert="$1" name value have missing=0
  find_zone
  while read -r name value; do
    [[ -z "$name" ]] && continue
    have=$(aws route53 list-resource-record-sets --hosted-zone-id "$ZONE_ID" --start-record-name "$name" --start-record-type CNAME --max-items 1 \
      --query 'ResourceRecordSets[0].[Name,ResourceRecords[0].Value]' --output text)
    if [[ "$have" == "$name"$'\t'"$value" ]]; then
      pass "validation CNAME in Route 53: $name"
    else
      bad "validation CNAME missing from Route 53: $name -> $value"
      missing=1
    fi
  done < <(validation_records "$cert")
  return "$missing"
}

