ID=$(aws sts get-caller-identity --query '[Account,Arn]' --output text 2>/dev/null) || stop "aws isn't signed in (try: aws configure, or aws sso login)."
[[ "${ID%%$'\t'*}" == "$ACCOUNT" ]] || stop "aws is signed in to account ${ID%%$'\t'*}, not $ACCOUNT."
