gh auth status >/dev/null 2>&1 || stop "gh isn't signed in (gh auth login)."
pass "GitHub: $(gh api user --jq .login) on $REPO"
note "Environment: $ENV_NAME · cluster $CLUSTER · service $SERVICE"
