# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Hearthside's image repository and container"
say "The deploy builds Hearthside into ECR repository $ECR_REPO and runs it as the"
say "'$CONTAINER' container in the $ENV_NAME task. Nothing routes to it yet."
if ECR_OUT=$(aws ecr describe-repositories --repository-names "$ECR_REPO" 2>&1); then
  pass "ECR repository $ECR_REPO exists"
elif ! grep -q RepositoryNotFoundException <<<"$ECR_OUT"; then
  stop "Couldn't check for ECR repository $ECR_REPO: $ECR_OUT"
else
  warn "No ECR repository $ECR_REPO. The deploy creates it if it may; create it here if the deploy failed on it."
  change "Create the repository (mutable tags, like the portfolio's: :dev and :prod move):" \
    aws ecr create-repository --repository-name "$ECR_REPO" --query 'repository.repositoryUri' --output text \
    || stop "The deploy needs this repository."
fi
discover_layout
IMAGE=$(aws ecs describe-task-definition --task-definition "$TASK_DEF_ARN" \
  --query "taskDefinition.containerDefinitions[?name=='$CONTAINER'].image | [0]" --output text)
if none "$IMAGE"; then
  bad "The service runs ${TASK_DEF_ARN##*/}, which has no $CONTAINER container: the deploy with Hearthside hasn't reached $ENV_NAME."
  if [[ "$ENV_NAME" == dev ]]; then
    note "Deploy dev (gh workflow run $WORKFLOW --ref dev --repo $REPO), wait for it, then re-run."
  else
    note "Promote to main and let the prod deploy finish, then re-run."
  fi
  exit 1
fi
pass "task definition ${TASK_DEF_ARN##*/} runs $IMAGE"
# A task of the current task definition: during a rolling deploy an older
# task (without Hearthside) may still be running beside it.
TASKS=$(aws ecs list-tasks --cluster "$CLUSTER" --service-name "$SERVICE" --desired-status RUNNING --query 'taskArns' --output text)
TASK="" STATUS=""
if [[ -n "$TASKS" && "$TASKS" != None ]]; then
  # shellcheck disable=SC2086
  read -r TASK STATUS < <(aws ecs describe-tasks --cluster "$CLUSTER" --tasks $TASKS \
    --query "tasks[?taskDefinitionArn=='$TASK_DEF_ARN'] | [0].[taskArn, containers[?name=='$CONTAINER'].lastStatus | [0]]" --output text 2>/dev/null) || true
fi
if [[ "$STATUS" == RUNNING ]]; then
  pass "the $CONTAINER container is RUNNING in task ${TASK##*/}"
else
  LOG_GROUP=$(aws ecs describe-task-definition --task-definition "$TASK_DEF_ARN" \
    --query "taskDefinition.containerDefinitions[?name=='$CONTAINER'].logConfiguration.options.\"awslogs-group\" | [0]" --output text)
  stop "The $CONTAINER container is ${STATUS:-not there} in task ${TASK##*/}. Its logs: aws logs tail $LOG_GROUP --log-stream-name-prefix ecs/$CONTAINER --since 1h"
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Security group: the ALB may reach port $PORT"
say "The ALB health-checks and forwards to the task's IP on port $PORT. The task's"
say "security group lets the ALB reach the portfolio on $FRONTEND_PORT; it needs the same for $PORT."
SGS=$(aws ecs describe-services --cluster "$CLUSTER" --services "$SERVICE" \
  --query 'services[0].networkConfiguration.awsvpcConfiguration.securityGroups' --output text)
# shellcheck disable=SC2086
SG_JSON=$(aws ec2 describe-security-groups --group-ids $SGS --output json)
read -r SG_VERDICT SG_ID SG_PERM < <(js '
  const sgs=JSON.parse(IN).SecurityGroups, fport=+process.argv[1], port=+process.argv[2];
  const covers=(p,n)=>p.IpProtocol==="-1"||((p.IpProtocol==="tcp"||p.IpProtocol==="6")&&p.FromPort<=n&&n<=p.ToPort);
  for (const sg of sgs) if (sg.IpPermissions.some(p=>covers(p,port))) { console.log("ok "+sg.GroupId); process.exit(0); }
  for (const sg of sgs) { const f=sg.IpPermissions.find(p=>covers(p,fport)); if (!f) continue;
    const d="ALB to Hearthside (#217)", perm={IpProtocol:"tcp",FromPort:port,ToPort:port};
    if (f.UserIdGroupPairs&&f.UserIdGroupPairs.length) perm.UserIdGroupPairs=f.UserIdGroupPairs.map(g=>({GroupId:g.GroupId,Description:d}));
    if (f.IpRanges&&f.IpRanges.length) perm.IpRanges=f.IpRanges.map(r=>({CidrIp:r.CidrIp,Description:d}));
    if (f.Ipv6Ranges&&f.Ipv6Ranges.length) perm.Ipv6Ranges=f.Ipv6Ranges.map(r=>({CidrIpv6:r.CidrIpv6,Description:d}));
    if (f.PrefixListIds&&f.PrefixListIds.length) perm.PrefixListIds=f.PrefixListIds.map(r=>({PrefixListId:r.PrefixListId,Description:d}));
    console.log("add "+sg.GroupId+" "+JSON.stringify([perm])); process.exit(0); }
  console.log("none");' "$FRONTEND_PORT" "$PORT" <<<"$SG_JSON") || true
case "$SG_VERDICT" in
  ok)  pass "security group $SG_ID already allows port $PORT" ;;
  add)
    say "Same sources as the portfolio's port $FRONTEND_PORT rule, on $PORT:"
    note "$SG_PERM"
    change "Allow them in on $PORT:" aws ec2 authorize-security-group-ingress --group-id "$SG_ID" --ip-permissions "$SG_PERM" --query 'Return' --output text \
      || stop "Without it the target group never turns healthy." ;;
  *) stop "No rule in $SGS lets anything reach port $FRONTEND_PORT, so there's nothing to copy. Check the service's networking by hand." ;;
esac
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Target group $TG_NAME (issue step 1)"
say "An IP target group on port $PORT, health-checked on /health (Hearthside answers it"
say "at once, even while Next starts). Settings are copied from the portfolio's target group."
find_tg
if [[ -n "$TG_ARN" ]]; then
  pass "target group $TG_NAME exists"
else
  read -r VPC_ID HC_INT HC_TIMEOUT HC_OK HC_BAD < <(aws elbv2 describe-target-groups --target-group-arns "$FRONTEND_TG_ARN" \
    --query 'TargetGroups[0].[VpcId,HealthCheckIntervalSeconds,HealthCheckTimeoutSeconds,HealthyThresholdCount,UnhealthyThresholdCount]' --output text) || true
  none "${VPC_ID:-}" && stop "Couldn't read the portfolio's target group."
  change "Create it in $VPC_ID:" aws elbv2 create-target-group --name "$TG_NAME" \
    --protocol HTTP --port "$PORT" --target-type ip --vpc-id "$VPC_ID" \
    --health-check-protocol HTTP --health-check-path /health --matcher HttpCode=200 \
    --health-check-interval-seconds "$HC_INT" --health-check-timeout-seconds "$HC_TIMEOUT" \
    --healthy-threshold-count "$HC_OK" --unhealthy-threshold-count "$HC_BAD" \
    --tags "Key=Name,Value=$TG_NAME" --query 'TargetGroups[0].TargetGroupArn' --output text \
    || stop "The later stages need the target group."
  find_tg
  DEREG=$(aws elbv2 describe-target-group-attributes --target-group-arn "$FRONTEND_TG_ARN" \
    --query "Attributes[?Key=='deregistration_delay.timeout_seconds'].Value | [0]" --output text)
  if ! none "$DEREG"; then
    aws elbv2 modify-target-group-attributes --target-group-arn "$TG_ARN" \
      --attributes "Key=deregistration_delay.timeout_seconds,Value=$DEREG" >/dev/null
    pass "deregistration delay ${DEREG}s, as the portfolio's"
  fi
fi
[[ -n "$TG_ARN" ]] || stop "Target group $TG_NAME not found."
write_env "${KEY_PREFIX}_HEARTHSIDE_TG_ARN" "$TG_ARN"
CHECK=$(aws elbv2 describe-target-groups --target-group-arns "$TG_ARN" --query 'TargetGroups[0].[Port,TargetType,HealthCheckPath]' --output text)
[[ "$CHECK" == "$PORT"$'\t'ip$'\t'/health ]] && pass "port $PORT, ip targets, health check /health" \
  || stop "$TG_NAME is set up differently ($CHECK); expected $PORT ip /health. Delete it and re-run, or fix it by hand."
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "ALB rule: $HOST → $TG_NAME (issue step 2)"
say "A host-header rule on the HTTPS listener sends $HOST to Hearthside; every other"
say "host keeps its rule. No DNS points at $HOST yet, so nobody reaches it until stage 8."
RULES=$(aws elbv2 describe-rules --listener-arn "$LISTENER_ARN" --output json)
say "The listener's rules now (lower priority wins):"
js '
  for (const r of JSON.parse(IN).Rules) {
    const hosts=r.Conditions.filter(c=>c.Field==="host-header").flatMap(c=>(c.HostHeaderConfig&&c.HostHeaderConfig.Values)||c.Values||[]);
    const other=r.Conditions.filter(c=>c.Field!=="host-header").map(c=>c.Field);
    const act=r.Actions.map(a=>a.Type==="forward"?"→ "+((a.TargetGroupArn||a.ForwardConfig.TargetGroups.map(t=>t.TargetGroupArn).join("+")).split("/")[1]):a.Type).join(" ");
    console.log("    "+String(r.Priority).padStart(7)+"  "+(hosts.join(" ")||"(any host)")+(other.length?" ["+other.join(",")+"]":"")+"  "+act);
  }' <<<"$RULES"
read -r RULE_ARN RULE_TG < <(js '
  const host=process.argv[1];
  const r=JSON.parse(IN).Rules.find(r=>r.Conditions.some(c=>c.Field==="host-header"&&((c.HostHeaderConfig&&c.HostHeaderConfig.Values)||c.Values||[]).includes(host)));
  if (r) { const a=r.Actions.find(a=>a.Type==="forward"); console.log(r.RuleArn+" "+(a?(a.TargetGroupArn||a.ForwardConfig.TargetGroups[0].TargetGroupArn):"none")); }' "$HOST" <<<"$RULES") || true
if [[ -n "${RULE_ARN:-}" ]]; then
  [[ "$RULE_TG" == "$TG_ARN" ]] || stop "A rule for $HOST already exists and doesn't forward to $TG_NAME: $RULE_ARN"
  pass "the rule for $HOST exists"
else
  # A free priority ahead of every rule that could also match this host: a
  # wildcard host, or no host condition at all.
  SUGGEST=$(js '
    const rules=JSON.parse(IN).Rules.filter(r=>!r.IsDefault);
    const hosts=r=>r.Conditions.filter(c=>c.Field==="host-header").flatMap(c=>(c.HostHeaderConfig&&c.HostHeaderConfig.Values)||c.Values||[]);
    const used=new Set(rules.map(r=>+r.Priority));
    const broad=rules.filter(r=>{const h=hosts(r); return !h.length||h.some(x=>/[*?]/.test(x));}).map(r=>+r.Priority);
    const limit=Math.min(50001,...broad); let p=1; while(used.has(p)) p++;
    console.log(p<limit?p:"");' <<<"$RULES")
  none "$SUGGEST" && stop "No free priority ahead of the broad rules above; free one by hand."
  ask "${KEY_PREFIX}_HEARTHSIDE_RULE_PRIORITY" "Priority for the new rule? [Enter for $SUGGEST]"
  PRIORITY_VAR="${KEY_PREFIX}_HEARTHSIDE_RULE_PRIORITY"
  PRIORITY="${!PRIORITY_VAR:-$SUGGEST}"
  [[ "$PRIORITY" =~ ^[0-9]+$ ]] || stop "Priority must be a number."
  change "Add the rule at priority $PRIORITY:" aws elbv2 create-rule --listener-arn "$LISTENER_ARN" --priority "$PRIORITY" \
    --conditions "[{\"Field\":\"host-header\",\"HostHeaderConfig\":{\"Values\":[\"$HOST\"]}}]" \
    --actions "[{\"Type\":\"forward\",\"TargetGroupArn\":\"$TG_ARN\"}]" \
    --query 'Rules[0].RuleArn' --output text \
    || stop "The target group can't join the service until a rule ties it to the ALB."
  RULE_ARN="$CHANGE_OUT"
  write_env "$PRIORITY_VAR" "$PRIORITY"
fi
write_env "${KEY_PREFIX}_HEARTHSIDE_RULE_ARN" "$RULE_ARN"
HTTP_DEFAULT=$(aws elbv2 describe-listeners --load-balancer-arn "$ALB_ARN" --query 'Listeners[?Port==`80`].DefaultActions[0].Type | [0]' --output text)
case "$HTTP_DEFAULT" in
  redirect) pass "port 80 redirects to HTTPS" ;;
  None|"") pass "no port 80 listener" ;;
  *) warn "The port 80 listener's default action is '$HTTP_DEFAULT', not a redirect: http://$HOST gets that, not Hearthside." ;;
esac
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Register $TG_NAME with the ECS service (issue step 1)"
say "update-service gives the service a second load balancer entry: the '$CONTAINER'"
say "container on $PORT. That's a service change; the task definition stays as the deploy left it."
LBS=$(aws ecs describe-services --cluster "$CLUSTER" --services "$SERVICE" --query 'services[0].loadBalancers' --output json)
if js 'process.exit(JSON.parse(IN).some(l=>l.targetGroupArn===process.argv[1])?0:1)' "$TG_ARN" <<<"$LBS"; then
  pass "the service already sends $CONTAINER:$PORT to $TG_NAME"
else
  NEW_LBS=$(js 'const l=JSON.parse(IN); l.push({targetGroupArn:process.argv[1],containerName:process.argv[2],containerPort:+process.argv[3]}); console.log(JSON.stringify(l))' \
    "$TG_ARN" "$CONTAINER" "$PORT" <<<"$LBS")
  warn "--load-balancers replaces the whole list, so the command below keeps the portfolio's entry."
  note "now: $(js 'console.log(JSON.parse(IN).map(l=>l.containerName+":"+l.containerPort+" → "+l.targetGroupArn.split("/")[1]).join(", "))' <<<"$LBS")"
  note "new: $(js 'console.log(JSON.parse(IN).map(l=>l.containerName+":"+l.containerPort+" → "+l.targetGroupArn.split("/")[1]).join(", "))' <<<"$NEW_LBS")"
  warn "This starts a rolling deployment of the $ENV_NAME service (as a deploy does)."
  note "From then on ECS also health-checks Hearthside: if it stops answering /health, ECS"
  note "replaces the whole task (backend and portfolio too), as it already does for the portfolio."
  change "Update the service:" aws ecs update-service --cluster "$CLUSTER" --service "$SERVICE" \
    --load-balancers "$NEW_LBS" --query 'service.deployments[0].rolloutState' --output text \
    || stop "Hearthside isn't reachable until the service registers its tasks in $TG_NAME."
fi
say "Waiting for the service to settle and Hearthside's target to turn healthy (a few minutes)..."
HEALTH=""
for _ in $(seq 1 40); do
  HEALTH=$(aws elbv2 describe-target-health --target-group-arn "$TG_ARN" --query 'TargetHealthDescriptions[].TargetHealth.State' --output text)
  some_healthy "$HEALTH" && break
  printf '  %s%s%s\n' "$DIM" "targets: ${HEALTH:-none yet}" "$RESET"
  sleep 15
done
some_healthy "$HEALTH" \
  || stop "$TG_NAME has no healthy target ($HEALTH). See: aws elbv2 describe-target-health --target-group-arn $TG_ARN"
pass "$TG_NAME targets: $HEALTH"
FRONT_HEALTH=$(aws elbv2 describe-target-health --target-group-arn "$FRONTEND_TG_ARN" --query 'TargetHealthDescriptions[].TargetHealth.State' --output text)
some_healthy "$FRONT_HEALTH" && pass "the portfolio's targets: $FRONT_HEALTH" \
  || warn "the portfolio's target group says: $FRONT_HEALTH (check it before going on)"
HEADERS=$(health_headers "$ALB_DNS" -k)
served_by_hearthside "$HEADERS" && pass "the ALB sends $HOST to Hearthside (X-Served-By: hearthside)" \
  || stop "Asking the ALB for https://$HOST/health didn't reach Hearthside:
$HEADERS"
# Three Next servers and the backend now share the task's memory.
SINCE=$(node -e 'console.log(new Date(Date.now()-3*3600e3).toISOString())')
NOW=$(node -e 'console.log(new Date().toISOString())')
MEM=$(aws cloudwatch get-metric-statistics --namespace AWS/ECS --metric-name MemoryUtilization \
  --dimensions "Name=ClusterName,Value=$CLUSTER" "Name=ServiceName,Value=$SERVICE" \
  --statistics Maximum --start-time "$SINCE" --end-time "$NOW" --period 3600 \
  --query 'max(Datapoints[].Maximum)' --output text 2>/dev/null || echo None)
if none "$MEM"; then
  note "No memory figures yet; check the service's MemoryUtilization in CloudWatch after a day."
elif js 'process.exit(+process.argv[1] > 80 ? 0 : 1)' "$MEM" </dev/null; then
  warn "The task's memory peaked at ${MEM%.*}% in the last 3 hours. Raise \"memory\" in .aws/*task-definition.json (3072 → 4096) in a PR."
else
  pass "task memory peak in the last 3 hours: ${MEM%.*}% of the task's limit"
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
discover_layout
DEFAULT_CERT=$(aws elbv2 describe-listener-certificates --listener-arn "$LISTENER_ARN" --query 'Certificates[?IsDefault].CertificateArn | [0]' --output text)
if [[ "$OWN_CERT" == no ]]; then
  stage "Certificate: the main one covers $HOST (issue step 3)"
  say "$HOST is one level under geoffthedeov.net, so the listener's main certificate"
  say "(geoffthedeov.net + *.geoffthedeov.net) covers it. Nothing to request or attach."
  warn "Don't reissue or replace the main certificate. Its renewal hangs on the CNAME checked below."
  SANS=$(aws acm describe-certificate --certificate-arn "$DEFAULT_CERT" --query 'Certificate.SubjectAlternativeNames' --output text)
  [[ "$SANS" == *'*.geoffthedeov.net'* ]] && pass "main certificate ${DEFAULT_CERT##*/} covers *.geoffthedeov.net" \
    || stop "The listener's default certificate ($SANS) doesn't cover *.geoffthedeov.net."
  check_validation_records "$DEFAULT_CERT" || stop "Put the missing CNAME back, or ACM can't renew the main certificate (2026-10-02)."
  read -r RENEW NOT_AFTER < <(aws acm describe-certificate --certificate-arn "$DEFAULT_CERT" --query 'Certificate.[RenewalEligibility,NotAfter]' --output text) || true
  [[ "$RENEW" == ELIGIBLE ]] && pass "renewal: ELIGIBLE (expires $NOT_AFTER)" || warn "renewal eligibility is $RENEW (expires $NOT_AFTER)"
else
  stage "Certificate: a second one for $HOST (issue step 3)"
  say "*.geoffthedeov.net can't cover the two-level $HOST, so it gets its own ACM"
  say "certificate, added to the HTTPS listener beside the main one (the ALB picks by SNI)."
  warn "Don't reissue or replace the main certificate (2026-10-02 outage). Don't use"
  warn "'modify-listener --certificates' either: that swaps the listener's default certificate."
  CERT_ARN=$(aws acm list-certificates --certificate-statuses PENDING_VALIDATION ISSUED \
    --query "CertificateSummaryList[?DomainName=='$HOST'].CertificateArn | [0]" --output text)
  if none "$CERT_ARN"; then
    change "Request a DNS-validated certificate for $HOST:" aws acm request-certificate \
      --domain-name "$HOST" --validation-method DNS --key-algorithm RSA_2048 \
      --idempotency-token t217hearthside --tags "Key=Name,Value=hearthside-$ENV_NAME" \
      --query 'CertificateArn' --output text || stop "Without it, browsers refuse https://$HOST."
    CERT_ARN="$CHANGE_OUT"
  else
    pass "certificate for $HOST exists: ${CERT_ARN##*/}"
  fi
  write_env "${KEY_PREFIX}_HEARTHSIDE_CERT_ARN" "$CERT_ARN"
  VALIDATION=""
  for _ in $(seq 1 12); do
    VALIDATION=$(validation_records "$CERT_ARN" | head -n1)
    [[ -n "$VALIDATION" && "$VALIDATION" != None* ]] && break
    sleep 5
  done
  VNAME="${VALIDATION%%$'\t'*}"; VVALUE="${VALIDATION#*$'\t'}"
  [[ -n "$VNAME" && "$VNAME" != None ]] || stop "ACM hasn't produced the validation record yet; re-run in a minute."
  find_zone
  if ! check_validation_records "$CERT_ARN"; then
    say "ACM proves you own $HOST through this CNAME, now and at every renewal:"
    note "$VNAME CNAME $VVALUE"
    warn "Keep it in Route 53 for as long as the certificate exists; renewal fails without it."
    change "Add it to zone $ZONE_ID:" aws route53 change-resource-record-sets --hosted-zone-id "$ZONE_ID" \
      --change-batch "{\"Comment\":\"ACM validation for $HOST (#217). Keep: renewal needs it.\",\"Changes\":[{\"Action\":\"UPSERT\",\"ResourceRecordSet\":{\"Name\":\"$VNAME\",\"Type\":\"CNAME\",\"TTL\":300,\"ResourceRecords\":[{\"Value\":\"$VVALUE\"}]}}]}" \
      --query 'ChangeInfo.Id' --output text || stop "The certificate can't be issued without it."
    check_validation_records "$CERT_ARN" || stop "The CNAME still isn't there."
  fi
  say "Waiting for ACM to issue it (usually a few minutes; up to 30)..."
  STATUS=""
  for _ in $(seq 1 60); do
    STATUS=$(aws acm describe-certificate --certificate-arn "$CERT_ARN" --query 'Certificate.Status' --output text)
    [[ "$STATUS" == ISSUED ]] && break
    [[ "$STATUS" == PENDING_VALIDATION ]] || stop "The certificate is $STATUS."
    printf '  %s%s%s\n' "$DIM" "status: $STATUS" "$RESET"
    sleep 30
  done
  [[ "$STATUS" == ISSUED ]] || stop "Still $STATUS; re-run later."
  pass "certificate ISSUED"
  if aws elbv2 describe-listener-certificates --listener-arn "$LISTENER_ARN" --query 'Certificates[].CertificateArn' --output text | tr '\t' '\n' | grep -qx "$CERT_ARN"; then
    pass "the listener already has it"
  else
    change "Add it to the HTTPS listener, beside the default certificate:" aws elbv2 add-listener-certificates \
      --listener-arn "$LISTENER_ARN" --certificates "CertificateArn=$CERT_ARN" --output text \
      || stop "Browsers refuse https://$HOST until the listener has it."
  fi
  AFTER_DEFAULT=$(aws elbv2 describe-listener-certificates --listener-arn "$LISTENER_ARN" --query 'Certificates[?IsDefault].CertificateArn | [0]' --output text)
  [[ "$AFTER_DEFAULT" == "$DEFAULT_CERT" ]] && pass "the listener's default certificate is unchanged (${DEFAULT_CERT##*/})" \
    || stop "The listener's default certificate changed to $AFTER_DEFAULT! Put ${DEFAULT_CERT##*/} back as default."
  SUBJECT=$(openssl s_client -connect "$ALB_DNS:443" -servername "$HOST" </dev/null 2>/dev/null | openssl x509 -noout -ext subjectAltName 2>/dev/null | tr -d '\r' || true)
  [[ "$SUBJECT" == *"DNS:$HOST"* ]] && pass "the ALB serves the new certificate for $HOST" \
    || warn "The ALB didn't present a certificate for $HOST yet (got: ${SUBJECT:-nothing}); it can take a minute."
  read -r RENEW NOT_AFTER < <(aws acm describe-certificate --certificate-arn "$CERT_ARN" --query 'Certificate.[RenewalEligibility,NotAfter]' --output text) || true
  [[ "$RENEW" == ELIGIBLE ]] && pass "renewal: ELIGIBLE (expires $NOT_AFTER; ACM renews it while the CNAME stays)" \
    || note "renewal eligibility: $RENEW (it turns ELIGIBLE once the listener uses it; expires $NOT_AFTER)"
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "DNS: $HOST → the ALB (issue step 4)"
say "An alias record sends $HOST to the ALB, like $PORTFOLIO_HOST."
find_zone
note "$PORTFOLIO_HOST now: $(aws route53 list-resource-record-sets --hosted-zone-id "$ZONE_ID" --query "ResourceRecordSets[?Name=='$PORTFOLIO_HOST.' && (Type=='A' || Type=='CNAME')].[Type,AliasTarget.DNSName,ResourceRecords[0].Value] | [0]" --output text)"
note "the ALB: $ALB_DNS ($ALB_IP_TYPE)"
TYPES=(A)
[[ "$ALB_IP_TYPE" == dualstack* ]] && TYPES+=(AAAA)
for TYPE in "${TYPES[@]}"; do
  HAVE=$(aws route53 list-resource-record-sets --hosted-zone-id "$ZONE_ID" --start-record-name "$HOST" --start-record-type "$TYPE" --max-items 1 \
    --query 'ResourceRecordSets[0].[Name,Type,AliasTarget.DNSName]' --output text)
  H_NAME="" H_TYPE="" H_ALIAS=""
  read -r H_NAME H_TYPE H_ALIAS <<<"$HAVE" || true
  H_ALIAS=$(printf '%s' "$H_ALIAS" | tr '[:upper:]' '[:lower:]')
  ALB_LC=$(printf '%s' "$ALB_DNS" | tr '[:upper:]' '[:lower:]')
  if [[ "$H_NAME" == "$HOST." && "$H_TYPE" == "$TYPE" ]]; then
    if [[ "$H_ALIAS" == *"$ALB_LC." ]]; then
      pass "$TYPE record for $HOST aliases the ALB"
      continue
    fi
    warn "$HOST already has a $TYPE record (${H_ALIAS/none/not an alias}); this replaces it."
  fi
  change "Point $HOST ($TYPE) at the ALB:" aws route53 change-resource-record-sets --hosted-zone-id "$ZONE_ID" \
    --change-batch "{\"Comment\":\"Hearthside on $ENV_NAME (#217)\",\"Changes\":[{\"Action\":\"UPSERT\",\"ResourceRecordSet\":{\"Name\":\"$HOST\",\"Type\":\"$TYPE\",\"AliasTarget\":{\"HostedZoneId\":\"$ALB_ZONE\",\"DNSName\":\"dualstack.$ALB_DNS\",\"EvaluateTargetHealth\":false}}}]}" \
    --query 'ChangeInfo.Id' --output text || stop "Without it nobody reaches $HOST."
  aws route53 wait resource-record-sets-changed --id "${CHANGE_OUT##*/}"
  pass "Route 53 has applied it"
done
ANSWER=$(aws route53 test-dns-answer --hosted-zone-id "$ZONE_ID" --record-name "$HOST" --record-type A --query '[ResponseCode,RecordData[0]]' --output text)
[[ "$ANSWER" == NOERROR* ]] && pass "Route 53 answers $HOST: ${ANSWER#*$'\t'}" || stop "Route 53 answers $HOST with $ANSWER."
say "Asking https://$HOST through public DNS (a resolver that cached 'no such host' may need a few minutes)..."
HEADERS=""
for _ in $(seq 1 20); do
  HEADERS=$(curl -sS -m 15 -D - -o /dev/null "https://$HOST/health" 2>&1 | tr -d '\r' || true)
  served_by_hearthside "$HEADERS" && break
  sleep 15
done
served_by_hearthside "$HEADERS" && pass "https://$HOST/health is Hearthside, over a trusted certificate" \
  || stop "https://$HOST/health didn't reach Hearthside:
$HEADERS"
API=$(curl -sS -m 15 -o /dev/null -w '%{http_code} %{content_type}' "https://$HOST/api/users/profile" || true)
[[ "$API" == 401*json* ]] && pass "https://$HOST/api reaches the backend (401 JSON without a session)" \
  || warn "https://$HOST/api/users/profile gave '$API'; expected the backend's 401 JSON."
PAGE=$(curl -sS -m 30 -o /dev/null -w '%{http_code}' "https://$HOST/" || true)
[[ "$PAGE" =~ ^(200|30[0-9])$ ]] && pass "https://$HOST/ answers $PAGE" || warn "https://$HOST/ answers $PAGE"
open_url "https://$HOST/"
pause "Hearthside should be open in your browser. Press Enter when you've looked"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud Console (issue step 5)"
CLIENT_ID=$(aws ecs describe-task-definition --task-definition "$TASK_DEF_ARN" \
  --query "taskDefinition.containerDefinitions[?name=='backend'] | [0].environment[?name=='GOOGLE_CLIENT_ID'].value | [0]" --output text)
none "$CLIENT_ID" && CLIENT_ID="(the client the GOOGLE_CLIENT_ID secret names)"
say "Google sign-in (#219) runs in the browser on $HOST, so Google must list it as a"
say "JavaScript origin on the OAuth client the backend uses:"
note "$CLIENT_ID"
open_url "https://console.cloud.google.com/apis/credentials"
step "Pick the project that owns that client, then under 'OAuth 2.0 Client IDs' open the one with that Client ID."
step "Authorized JavaScript origins → ADD URI → https://$HOST"
step "Authorized redirect URIs → ADD URI → https://$HOST/api/google-calendar/callback"
note "  Calendar Connect still returns through https://$PORTFOLIO_HOST/api/google-calendar/callback,"
note "  which stays. The Hearthside one is harmless now and saves a trip here if it moves."
step "Leave the portfolio's entries as they are. SAVE."
step "OAuth consent screen → Branding → Authorized domains should list geoffthedeov.net (it covers $HOST)."
note "Google says changes can take from 5 minutes to a few hours."
pause "Press Enter once it's saved"
say "Check: this asks Google to sign in with the new redirect URI. 'Error 400: redirect_uri_mismatch'"
say "means it isn't saved yet; an account chooser means it is (close the tab, nothing is granted)."
if [[ "$CLIENT_ID" != "("* ]]; then
  open_url "https://accounts.google.com/o/oauth2/v2/auth?client_id=$CLIENT_ID&redirect_uri=https%3A%2F%2F$HOST%2Fapi%2Fgoogle-calendar%2Fcallback&response_type=code&scope=openid"
fi
step "The JavaScript origin: reopen the client in the console; https://$HOST is listed. Once #219 ships, the Google button on https://$HOST/login signs in."
confirm "Is https://$HOST listed as a JavaScript origin, with the redirect URI saved?" \
