# ── 10 ────────────────────────────────────────────────────────────────────
stage "Dev and prod sign with different JWT secrets (issue step 7)"
say "A dev login must never work on prod, or the reverse (stories 8 and 9). Each backend's"
say "JWT_SECRET comes from Secrets Manager; this compares the two values by hash and never prints them."
jwt_arn() {
  local td
  td=$(aws ecs describe-services --cluster "$1" --services "$2" --query 'services[0].taskDefinition' --output text)
  aws ecs describe-task-definition --task-definition "$td" \
    --query "taskDefinition.containerDefinitions[?name=='backend'] | [0].secrets[?name=='JWT_SECRET'].valueFrom | [0]" --output text
}
secret_hash() {
  aws secretsmanager get-secret-value --secret-id "$1" --query SecretString --output text | node -e '
    const s=require("fs").readFileSync(0,"utf8").replace(/\r?\n$/,"");
    console.log(s.length+" "+require("crypto").createHash("sha256").update(s).digest("hex"));' | tr -d '\r'
}
PROD_JWT=$(jwt_arn "$PROD_CLUSTER" "$PROD_SERVICE")
DEV_JWT=$(jwt_arn "$DEV_CLUSTER" "$DEV_SERVICE")
none "$PROD_JWT" && stop "Prod's running task definition takes no JWT_SECRET from Secrets Manager."
none "$DEV_JWT" && stop "Dev's running task definition takes no JWT_SECRET from Secrets Manager."
[[ "$PROD_JWT" != "$DEV_JWT" ]] && pass "different secrets: ${PROD_JWT##*:secret:} and ${DEV_JWT##*:secret:}" \
  || bad "dev and prod read the same secret: $PROD_JWT"
PROD_LEN=0 PROD_HASH="" DEV_LEN=0 DEV_HASH=""
read -r PROD_LEN PROD_HASH < <(secret_hash "$PROD_JWT") || true
read -r DEV_LEN DEV_HASH < <(secret_hash "$DEV_JWT") || true
[[ -n "$PROD_HASH" && -n "$DEV_HASH" ]] || stop "Couldn't read both secrets' values (secretsmanager:GetSecretValue on $PROD_JWT and $DEV_JWT)."
(( PROD_LEN >= 32 && DEV_LEN >= 32 )) && pass "both are at least 32 characters" || warn "a JWT secret is short (prod $PROD_LEN, dev $DEV_LEN characters)"
if [[ "$PROD_JWT" != "$DEV_JWT" && "$PROD_HASH" != "$DEV_HASH" ]]; then
  pass "dev's and prod's JWT_SECRET values differ"
else
  bad "dev and prod sign tokens with the same JWT secret: a token from one works on the other."
  say "The fix is a new dev secret: everyone signed in on dev signs in again; prod is untouched."
  if [[ "$PROD_JWT" != "$DEV_JWT" ]]; then
    NEW_SECRET=$(node -e 'console.log(require("crypto").randomBytes(48).toString("hex"))' | tr -d '\r')
    if change "Store a new random value in dev's secret (the value isn't shown):" \
        aws secretsmanager put-secret-value --secret-id "$DEV_JWT" --secret-string "$NEW_SECRET" --query VersionId --output text; then
      change "Restart dev's backend so it reads it:" aws ecs update-service --cluster "$DEV_CLUSTER" --service "$DEV_SERVICE" \
        --force-new-deployment --query 'service.deployments[0].rolloutState' --output text \
        || SKIPPED+=("restart dev: aws ecs update-service --cluster $DEV_CLUSTER --service $DEV_SERVICE --force-new-deployment")
    else
      SKIPPED+=("give dev its own JWT_SECRET value ($DEV_JWT)")
    fi
    unset NEW_SECRET
  else
    SKIPPED+=("point dev's task definition at its own JWT_SECRET secret (both read $PROD_JWT)")
  fi
fi
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Turn Hearthside on for $ENV_NAME (issue step 6)"
say "HEARTHSIDE_LIVE on the GitHub '$GH_ENV' environment is the switch. At the next deploy it sets:"
step "the backend's HEARTHSIDE_URL=https://$HOST: Game Night links (bell, emails, calendar and"
say "    Discord events) point at Hearthside (#214), and $HOST joins the allowed sites for reset,"
say "    verify and Google Calendar return links (#215);"
step "the portfolio's NEXT_PUBLIC_HEARTHSIDE_URL, for its Hearthside links and /game-night redirects (#234)."
say "SESSION_COOKIE_ORIGINS already lists https://$HOST, so the live channel accepts its cookie:"
ORIGINS=$(aws ecs describe-task-definition --task-definition "$TASK_DEF_ARN" \
  --query "taskDefinition.containerDefinitions[?name=='backend'] | [0].environment[?name=='SESSION_COOKIE_ORIGINS'].value | [0]" --output text)
[[ ",$ORIGINS," == *",https://$HOST,"* ]] && pass "SESSION_COOKIE_ORIGINS=$ORIGINS" \
  || stop "The running backend's SESSION_COOKIE_ORIGINS ($ORIGINS) lacks https://$HOST; deploy the workflow that adds it first."
NOW_LIVE=$(gh api "repos/$REPO/environments/$GH_ENV/variables/HEARTHSIDE_LIVE" --jq .value 2>/dev/null || true)
if [[ "$NOW_LIVE" == true ]]; then
  pass "HEARTHSIDE_LIVE is already true on $GH_ENV"
else
  warn "Only switch on once the stages above passed: links sent from now on point at $HOST."
  if change "Turn the switch on:" gh variable set HEARTHSIDE_LIVE --env "$GH_ENV" --body true --repo "$REPO"; then
    NOW_LIVE=true
  else
    SKIPPED+=("turn Hearthside on: gh variable set HEARTHSIDE_LIVE --env $GH_ENV --body true --repo $REPO, then redeploy")
  fi
fi
RUNNING_URL=$(aws ecs describe-task-definition --task-definition "$TASK_DEF_ARN" \
  --query "taskDefinition.containerDefinitions[?name=='backend'] | [0].environment[?name=='HEARTHSIDE_URL'].value | [0]" --output text)
if [[ "$NOW_LIVE" == true && "$RUNNING_URL" != "https://$HOST" ]]; then
  say "The running backend doesn't have it yet (HEARTHSIDE_URL='${RUNNING_URL/None/}'); it needs a deploy."
  [[ "$ENV_NAME" == prod ]] && note "A prod deploy is followed, as always, by the job that rebases dev onto main and redeploys dev."
  if change "Deploy $ENV_NAME now:" gh workflow run "$WORKFLOW" --ref "$DEPLOY_REF" --repo "$REPO"; then
    sleep 5
    RUN_ID=$(gh run list --workflow "$WORKFLOW" --repo "$REPO" --limit 1 --json databaseId --jq '.[0].databaseId')
    note "run: https://github.com/$REPO/actions/runs/$RUN_ID"
    if confirm "Watch it until it finishes (10-60 minutes)?"; then
      gh run watch "$RUN_ID" --repo "$REPO" --exit-status >/dev/null || stop "The deploy failed: https://github.com/$REPO/actions/runs/$RUN_ID"
      TD=$(aws ecs describe-services --cluster "$CLUSTER" --services "$SERVICE" --query 'services[0].taskDefinition' --output text)
      RUNNING_URL=$(aws ecs describe-task-definition --task-definition "$TD" \
        --query "taskDefinition.containerDefinitions[?name=='backend'] | [0].environment[?name=='HEARTHSIDE_URL'].value | [0]" --output text)
    fi
  else
    SKIPPED+=("deploy $ENV_NAME so the switch applies: gh workflow run $WORKFLOW --ref $DEPLOY_REF --repo $REPO")
  fi
fi
if [[ "$RUNNING_URL" == "https://$HOST" ]]; then
  pass "the $ENV_NAME backend runs with HEARTHSIDE_URL=https://$HOST"
elif [[ "$NOW_LIVE" == true ]]; then
  SKIPPED+=("after the deploy, re-run '$0 $ENV_NAME' to confirm the backend has HEARTHSIDE_URL=https://$HOST")
fi
note "To turn it off again: gh variable set HEARTHSIDE_LIVE --env $GH_ENV --body false --repo $REPO, then deploy."
note "The ALB rule, certificate and DNS can stay; with the switch off nothing links to $HOST."
pause

finish
if [[ "$ENV_NAME" == dev ]]; then
  note "Next: try dev end to end on https://$HOST, then after the promotion to main: $0 prod"
else
  note "Hearthside is live: https://$HOST"
fi
